def join_gpxs(xmls: Iterable[AnyStr]) ->str:
    xmls_list = list(xmls)
    if not xmls_list:
        return '<?xml version="1.0" encoding="UTF-8"?>\n<gpx></gpx>'

    dom = mod_minidom.parseString(xmls_list[0])
    gpx_node = _find_gpx_node(dom)

    for xml in xmls_list[1:]:
        other_dom = mod_minidom.parseString(xml)
        other_gpx_node = _find_gpx_node(other_dom)

        if other_gpx_node:
            for child_node in list(other_gpx_node.childNodes):
                imported_node = dom.importNode(child_node, True)
                gpx_node.appendChild(imported_node)

    return dom.toxml()

def _find_gpx_node(dom: Any) ->Any:
    for child_node in dom.childNodes:
        if child_node.nodeName == 'gpx':
            return child_node
    return None
